public class CalculadoraSwitch {
    public static void main(String[] args) {
        String operacion = "multiplicar";
        double a = 8.0;
        double b = 3.0;

        // TODO: Usa switch expression con sintaxis de flecha (->)
        // para asignar el resultado según:
        // "sumar" → a + b
        // "restar" → a - b
        // "multiplicar" → a * b
        // "dividir" → si b != 0, a / b; si no, muestra error y usa 0
        // default → 0
        // Usa yield para la división (necesita un bloque)
        // Imprime: "8.0 multiplicar 3.0 = 24.0"

    }
}

solution:
public class CalculadoraSwitch {
    public static void main(String[] args) {
        String operacion = "multiplicar";
        double a = 8.0;
        double b = 3.0;

        double resultado = switch (operacion) {
            case "sumar" -> a + b;
            case "restar" -> a - b;
            case "multiplicar" -> a * b;
            case "dividir" -> {
                if (b == 0) {
                    System.out.println("Error: no se puede dividir entre cero");
                    yield 0;
                }
                yield a / b;
            }
            default -> 0;
        };

        System.out.printf("%.1f %s %.1f = %.1f%n", a, operacion, b, resultado);
    }
}

