solution:
public class Peaje {
    enum TipoVehiculo { COCHE, MOTO, CAMION, AUTOBUS }

    public static void main(String[] args) {
        TipoVehiculo tipo = TipoVehiculo.CAMION;
        boolean esPremium = true;

        double tarifaBase = switch (tipo) {
            case COCHE -> 5.0;
            case MOTO -> 2.5;
            case CAMION -> 10.0;
            case AUTOBUS -> 15.0;
        };

        double total = esPremium ? tarifaBase * 0.8 : tarifaBase;

        System.out.printf("%s - Tarifa: $%.1f - Premium: %s - Total: $%.1f%n",
                tipo, tarifaBase, esPremium, total);
    }
}
